[
  {
    "statement": "Two controlled, replicated trials in Spain and the United Kingdom measured the effects of adding municipal compost or wastes to soil.",
    "citations": [
      "890"
    ]
  },
  {
    "statement": "One trial found that adding municipal compost to semi-arid soils greatly reduced soil loss and water runoff.",
    "citations": [
      "890"
    ]
  },
  {
    "statement": "Another trial reported mixed results when adding composts and wastes.",
    "citations": [
      "890"
    ]
  },
  {
    "statement": "Soil types covered by studies on municipal compost were coarse loamy and sandy loam.",
    "citations": [
      "890"
    ]
  }
]
